import {displayNumber,precisionInputAttributes,readPrecisionInput,bindPrecisionInput,bindPrecisionInputs,setPrecisionInput} from './number-display.js';
import {bindGuidedMessages} from './guided-localization.js';
import {marginPhaseControlsHTML,marginPathChartHTML,isYearlyMarginPath,YEARLY_MARGIN_PATH_VERSION,MAX_NEAR_TERM_YEARS} from './margin-path-view.js';
import {capitalPathDefaults,capitalPathIssues,capitalEfficiencyDiagnostics,isYearlyCapitalPath,YEARLY_CAPITAL_PATH_VERSION,MAX_YEARLY_CAPITAL_YEARS} from './capital-efficiency.js';
import {capitalPhaseControlsHTML,capitalPathModeDescription,capitalEfficiencyPanelHTML} from './capital-efficiency-view.js';
import {defaults,valueCompany} from './engine.js';
import {mountSimulation} from './simulation-view.js';
import {enterPanel,reducedMotion,cancelMotion,updateFeedback} from './motion.js';
import {prepareFlowTables} from './document-flow.js';
import {currentSnapshot,currentIssues,calculateCurrent,safeDraft,quoteComparison,freezeCurrent,waccWorksheet,researchCaseFor,loadResearchedBaseCase,markDraftEdited,fetchBaseCases,currentClaimsEvidence,claimsDefinition,claimsDefaults,claimsSensitivity,currentEconomicShareBasis,operatingProfileDefinition,operatingAssumptions,independentGrowthProfile,valueCurrentWithClaims} from './current-model.js';
import {assumptionEvidence,formatEvidenceValue} from './assumption-history.js';
import {renderHistorySeries,renderHistoryCoverage} from './history-view.js';
import {createContextualEvidencePanel} from './contextual-evidence.js';
import {updateGrowthChart,updateProfitChart,renderApprovedEvidence,evidenceComparison,releaseApprovedChart} from './approved-charts.js';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(value,digits=1)=>displayNumber(value,digits);
const pc=v=>Number.isFinite(v)?num(v*100,1)+'%':'—';
const safeURL=u=>/^https?:\/\//.test(u||'')?u:'#';
// Damodaran's order: the story first, then the four value drivers it implies,
// then the bridge to equity. Sources and Details are reference, not steps.
const groups=[{id:1,name:'Story'},{id:2,name:'Growth'},{id:3,name:'Profitability'},{id:4,name:'Investment'},{id:5,name:'Risk'},{id:6,name:'Equity'},{id:0,name:'Sources'},{id:7,name:'Details'}];
let library,company,raw,snapshot,draft,historyData=null,marketReferences=null,baseCases=null,storageOkay=true;
let releaseSimulation=()=>{},simulationTimer=null,firstMount=true,evidencePanel=null;
const workspaceViews=new Map(),inputUndo=new Map(),historySelections=new Map(),fullInputUndo=new Set();
const defaultHistoryField={0:'bridge',1:'normalizationDelta',2:'growth',3:'targetMargin',4:'salesCapital',5:'wacc',6:'otherClaims',7:'growth'};
let activeEvidenceName=null;
let currentView='inputs',mobileView='inputs',beforeEvidenceMobile='result',activeEdit=null;
const app=$('#guided-app'),sessionDrafts=new Map(),undoBaseCases=new Map(),undoOperatingPaths=new Map();
// Locale changes update owned text nodes only; they never render, store, or calculate.
if(typeof bindGuidedMessages==='function')bindGuidedMessages(app);
const key=()=>`valuation-lab-guided-v5:${company.ticker}:${raw?.id}`;
function store({preserveTimestamp=false}={}){
 if(!preserveTimestamp)draft.updatedAt=new Date().toISOString();sessionDrafts.set(key(),JSON.stringify(draft));
 try{localStorage.setItem(key(),JSON.stringify(draft));localStorage.setItem('valuation-lab-guided-selection',JSON.stringify({ticker:company.ticker,id:raw?.id}));}catch{storageOkay=false}
 const scenario=$('#guided-scenario-state');if(scenario)scenario.textContent=draft.assumptionProvenance?.userEdited?'Your edits':'Earlier Guided case';
 const state=$('#base-case-state');if(state)state.textContent=researchState();
 const el=$('#guided-save-state');if(el)el.textContent=storageOkay?'Saved on this device':'Storage unavailable · export before leaving';
}
function download(name,data){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function choose(ticker,id){
 evidencePanel?.destroy();evidencePanel=null;activeEvidenceName=null;activeEdit=null;
 company=library.companies.find(c=>c.ticker===ticker)||library.companies[0];
 raw=company.snapshots?.find(s=>s.id===id)||company.snapshots?.find(s=>s.id===company.currentSnapshotId)||company.snapshots?.find(s=>['ttm','annual-reference'].includes(s.snapshotMode))||company.snapshots?.[0]||{};
 snapshot=currentSnapshot(company,raw);let saved;try{saved=JSON.parse(sessionDrafts.get(key())||localStorage.getItem(key())||'null')}catch{}
 draft=safeDraft(saved,company,raw,{baseCases});firstMount=true;currentView=workspaceViews.get(key())||'inputs';store();render();
}
function table(title,head,rows){return `<div class="table-wrap"><table class="workspace-table"><caption><span class="sr-only">${esc(company.ticker)} · ${esc(title)}</span></caption><thead><tr>${head.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>'<tr>'+r.map((v,i)=>i===0?`<th scope="row">${v}</th>`:`<td>${v}</td>`).join('')+'</tr>').join('')}</tbody></table></div>`}
function evidenceFor(k){try{return assumptionEvidence(historyData,company.ticker,k,{snapshot,marketReferences,cutoff:draft.cutoff})}catch{return {title:'Company history',series:[],summary:'Verified historical comparison is unavailable for this field.',cautions:[],status:'unavailable'}}}
function historyValue(v,e){try{return formatEvidenceValue(v,e.unit)}catch{return num(v,2)}}
function historySeries(series,unit,title){return renderHistorySeries(series,unit,title)}
const researchLabels={growth:'Initial revenue growth',targetMargin:'Mature operating margin',tax:'Cash tax rate',salesCapital:'Incremental sales / capital',wacc:'Cost of capital',terminalGrowth:'Stable growth',terminalROIC:'Mature marginal ROIC',otherAssets:'Other assets',otherClaims:'Other claims'};
const researchUnit=k=>k==='salesCapital'?'multiple':['otherAssets','otherClaims','normalizationDelta'].includes(k)?snapshot.currency+' millions':'percent';
function researchRationale(k){const c=researchCaseFor(baseCases,company,raw),reason=c?.rationale?.[k]||(k==='normalizationDelta'?c?.normalization?.adjustmentReason:null);if(!reason)return '';const value=k==='normalizationDelta'?c.normalization?.normalizationDelta:c.assumptions[k];return `<details class="driver-rationale"><summary>${c.displayLabel?'Assumption reasoning':'Base-case reasoning'} <span>${esc(formatEvidenceValue(value,researchUnit(k)))}${['otherAssets','otherClaims','normalizationDelta'].includes(k)?'m':''}</span></summary><p>${esc(reason)}</p><p class="micro">Research judgment as of ${esc(c.asOf||baseCases.asOf)}. Your input stays editable; the source history below is a separate reference.</p></details>`;}
function researchState(){if(isFlexible())return 'Your growth path · stable growth in year '+draft.assumptions.years;if(company.ticker==='AAOI'&&raw.id==='AAOI-TTM-2026-06-30'&&draft.operatingProfile?.id!=='aaoi-capacity-ramp-v1')return 'Saved / generic linear path · staged research available';const p=draft.assumptionProvenance,c=researchCaseFor(baseCases,company,raw);return p?.kind==='researched-base-case'?(p.userEdited?'Your edits · based on researched assumptions':(c?.displayLabel||'Researched base case')+' · '+(p.asOf||'dated')):p?.kind==='user-draft'?'Saved inputs kept · research case ready':'Generic inputs · research case ready';}
function normalizationBanner(){if(!Number.isFinite(draft.normalizationDelta)||draft.normalizationDelta===0)return '';const margin=(snapshot.ebit+draft.normalizationDelta)/snapshot.revenue;return `<div class="base-normalization applied-normalization"><b>Starting EBIT adjusted by ${num(draft.normalizationDelta)}m ${esc(snapshot.currency)}</b><p>Model starting margin: ${pc(margin)}. This is an analyst adjustment; reported EBIT remains unchanged.</p>${draft.adjustmentSource?`<a href="${esc(safeURL(draft.adjustmentSource))}" target="_blank" rel="noopener">Adjustment source ↗</a>`:''}</div>`;}
function completeResearchPanel(){
 if(company.researchImported)return '';
 return `<section class="guided-research-preset" aria-label="Complete company research"><div><b>Our complete ${esc(company.ticker)} research case</b><p>Use research opens Year-by-year with the reviewed revenue, margin, direct investment, dated claims and Monte Carlo assumptions. Guided keeps this separate simplified draft.</p></div><button id="use-research" class="primary">Use research</button><p id="complete-research-status" role="status" class="micro"></p></section>`;
}
function baseCasePanel(){
 const c=researchCaseFor(baseCases,company,raw);if(!c)return normalizationBanner()+`<p class="base-case-fallback">${draft.assumptionProvenance?.kind==='generic-default'&&!draft.assumptionProvenance?.userEdited?'Generic fallback assumptions':'Saved inputs retained'} · no researched case is available for this exact baseline.</p>`;
 const sources=(c.sourceIds||[]).map(id=>Array.isArray(baseCases.sources)?baseCases.sources.find(s=>s.id===id):baseCases.sources?.[id]).filter(Boolean);
 const status=researchState();
 return `<div class="base-case-control">${normalizationBanner()}${(c.economicChecks?.negativeFCFFYears||[]).length>=5?`<p class="base-case-warning">${esc(c.displayLabel||'Research case')}: negative FCFF in ${c.economicChecks.negativeFCFFYears.length} of 10 forecast years. This simple model does not model the funding needed to sustain that cash burn.</p>`:c.economicChecks?.terminalValueShareOfOperatingEV>.75?`<p class="base-case-warning">Research case: terminal value supplies ${pc(c.economicChecks.terminalValueShareOfOperatingEV)} of operating value, so the mature-growth and return assumptions have an outsized effect.</p>`:''}<div class="base-case-bar"><span id="base-case-state">${esc(status)}</span><button id="load-base-case" class="quiet">Reload earlier Guided inputs</button>${undoBaseCases.has(key())?'<button id="undo-base-case" class="text-button">Undo load</button>':''}</div><p id="base-case-action-status" role="status" class="micro"></p><details id="base-case-panel" class="base-case-panel"><summary><span>Earlier Guided inputs · ${esc(company.ticker)}</span><small>Legacy scalar case & sources</small></summary><p>${esc(c.summary)}</p><p class="micro">Dated ${esc(c.asOf||baseCases.asOf)}. These are analyst judgments, not reported facts, fitted probabilities or investment advice. Loading replaces the model assumptions, stated starting-profit normalization and any named company-specific operating profile. Your notes and quote are retained.</p>${c.normalization?.normalizationDelta?`<div class="base-normalization"><b>Starting operating-profit adjustment: ${esc(formatEvidenceValue(c.normalization.normalizationDelta,snapshot.currency+' millions'))}m ${esc(snapshot.currency)}</b><p>${esc(c.normalization.adjustmentReason)}</p><a href="${esc(safeURL(c.normalization.adjustmentSource))}" target="_blank" rel="noopener">Adjustment source ↗</a></div>`:''}<div class="base-case-comparison">${Object.entries(researchLabels).map(([k,label])=>`<article class="base-case-driver"><div class="base-case-driver-top"><span>${label}</span><strong>${esc(formatEvidenceValue(c.assumptions[k],researchUnit(k)))}${['otherAssets','otherClaims'].includes(k)?'m':''}</strong></div><small class="base-case-current">Current: ${esc(formatEvidenceValue(draft.assumptions[k],researchUnit(k)))}${['otherAssets','otherClaims'].includes(k)?'m':''}</small>${c.rationale?.[k]?`<p>${esc(c.rationale[k])}</p>`:''}</article>`).join('')}</div>${c.reportedAnchors?.length?`<h3>Reported reference points</h3><ul>${c.reportedAnchors.map(a=>`<li>${esc(a.text||`${a.periodEnd}: revenue ${num(a.revenue)}m ${a.currency}; reported operating margin ${pc(a.operatingMargin)}.`)}</li>`).join('')}</ul>`:''}${c.economicChecks?`<h3>What the research case implies</h3><p>Year 10 revenue: ${num(c.economicChecks.revenueMultiple10Years,1)}× the starting level. Negative FCFF: ${(c.economicChecks.negativeFCFFYears||[]).length} of 10 years. ${Number.isFinite(c.economicChecks.terminalValueShareOfOperatingEV)?`Terminal value supplies ${pc(c.economicChecks.terminalValueShareOfOperatingEV)} of operating value.`:'Terminal-value share is not meaningful when operating value is nonpositive.'} These are computed consequences of the proposed assumptions.</p>`:''}${c.bridgePolicy?`<h3>Claims and model limits</h3><p>${esc(typeof c.bridgePolicy==='string'?c.bridgePolicy:c.bridgePolicy.note||'Claims remain unreviewed.')}</p>`:''}${Array.isArray(c.modelLimits)?`<ul>${c.modelLimits.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:typeof c.modelLimits==='string'?`<p>${esc(c.modelLimits)}</p>`:''}${c.uncertainties?.length?`<h3>What could change this case</h3><ul>${c.uncertainties.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:''}${sources.length?`<ul class="base-case-sources">${sources.map(s=>`<li><a href="${esc(safeURL(s.url||s.sourceUrl||s.href))}" target="_blank" rel="noopener">${esc(s.title||s.label||s.id||'Primary source')} ↗</a></li>`).join('')}</ul>`:''}<a class="base-case-ledger" href="./data/company-base-cases.json" target="_blank" rel="noopener">Complete case and source ledger ↗</a></details></div>`;
}
function bindBaseCase(){
 const complete=$('#use-research');if(complete)complete.onclick=()=>{try{const annual=$('#renewed-research-app');if(typeof annual?.useResearch!=='function')throw Error('The annual research workspace is still loading or unavailable. Your Guided draft is unchanged.');annual.useResearch(company.ticker,{originPage:'current'});}catch(error){$('#complete-research-status').textContent=error.message;}};
 const load=$('#load-base-case');if(load)load.onclick=()=>{try{const prior=structuredClone(draft);draft=loadResearchedBaseCase(draft,company,raw,baseCases);inputUndo.delete(key());activeEdit=null;undoBaseCases.set(key(),prior);store();render();$('#base-case-panel').open=true;$('#base-case-action-status').textContent='Research assumptions loaded. You can undo this change.';}catch(e){$('#base-case-action-status').textContent=e.message}};
 const undo=$('#undo-base-case');if(undo)undo.onclick=()=>{const previous=undoBaseCases.get(key());if(!previous)return;draft=structuredClone(previous);inputUndo.delete(key());activeEdit=null;undoBaseCases.delete(key());store();render();$('#base-case-panel').open=true;$('#base-case-action-status').textContent='Your previous draft has been restored.';};
}
const evidenceAssumption=k=>k==='normalizationDelta'?draft.normalizationDelta:draft.assumptions[k];
function historyPanel(k){
 const e=evidenceFor(k),series=e.series||[],sources=e.sources||[],context=e.contextSeries||[],components=e.components||[];
 const contextBlock=g=>`<div class="history-context"><div class="history-context-title">${esc(g.title)}${g.unit&&!['percent','multiple','x'].includes(g.unit)?` · ${esc(g.unit)}`:''}</div>${historySeries(g.series||[],g.unit,g.title)}</div>`;
 return `<div class="assumption-history" data-history="${k}"><p class="approved-comparison" data-live-evidence-comparison="${k}">${esc(evidenceComparison(e,evidenceAssumption(k),k))}</p><div class="history-heading"><span>${esc(e.title||'Company history')}</span><span class="history-status">${e.kind==='proxy'?'Historical proxy':series.length?'Annual history':'Evidence context'}</span></div>${renderHistoryCoverage(e.coverage)}${series.length?historySeries(series,e.unit,e.title):''}${components.length?`<div class="history-components">${components.map(p=>`<a href="${esc(safeURL(p.sourceUrl))}" target="_blank" rel="noopener"><span>${esc(p.label)}<small>${esc(p.date)}${p.currency?' · '+esc(p.currency):''}</small></span><b>${esc(historyValue(p.value,{unit:p.unit}))}</b></a>`).join('')}</div>`:''}${e.ttm?`<div class="history-ttm"><span>${esc(e.ttm.period)} · separate from FY range</span><b>${esc(historyValue(e.ttm.value,e))}</b></div>`:''}<p class="history-summary">${esc(e.summary||'No verified comparable history in the saved source library.')}</p>${e.range?`<p class="history-range">${esc(e.range.label||'Observed range')} <b>${esc(historyValue(e.range.min,e))}–${esc(historyValue(e.range.max,e))}</b>${Number.isFinite(e.range.median)?` · median ${esc(historyValue(e.range.median,e))}`:''}</p>`:''}${context.slice(0,series.length?1:2).map(contextBlock).join('')}<details class="history-method"><summary>Sources & comparability <span aria-hidden="true">↗</span></summary>${context.slice(series.length?1:2).map(contextBlock).join('')}${e.formula?`<p>${esc(e.formula)}</p>`:''}${(e.cautions||[]).map(c=>`<p>${esc(c.replace('ten-year forecast',draft.assumptions.years+'-year growth forecast'))}</p>`).join('')}${series.filter(p=>!Number.isFinite(p.value)).map(p=>`<p><b>${esc(p.period)} unavailable:</b> ${esc(p.detail||'No verified comparable observation.')}</p>`).join('')}${sources.length?`<ul>${sources.map(s=>`<li><a href="${esc(safeURL(typeof s==='string'?s:s.url||s.sourceUrl||s.sourceURL))}" target="_blank" rel="noopener">${esc(typeof s==='string'?'Original source':s.label||s.title||s.period||'Original source')} ↗</a></li>`).join('')}</ul>`:'<p>Missing evidence is not zero. No historical value is inferred from your assumption.</p>'}</details></div>`;
}
function field(k,label,help,scale=100,unit='%',min=0,max=100,step=.5){
 const value=Number.isFinite(draft.assumptions[k])?Math.round(draft.assumptions[k]*scale*1e6)/1e6:'';
 const unitDescription=unit==='%'?'Percent':unit==='×'?'Times':unit==='m'?`${snapshot.currency} millions`:unit;
 return `<article class="driver-card${unit==='m'?' driver-card--amount':''}"><div class="driver-top"><label for="g-${k}">${label}<span class="assumption-tag">Your assumption</span></label><div class="driver-number"><input id="g-${k}" type="number" inputmode="decimal" data-assumption="${k}" data-scale="${scale}" ${precisionInputAttributes(draft.assumptions[k],scale)} min="${min}" max="${max}" step="${step}" aria-describedby="g-hint-${k}"><span>${unit}</span></div></div><input class="driver-range" type="range" data-slider="${k}" data-scale="${scale}" value="${value}" min="${min}" max="${max}" step="${step}" aria-label="${esc(label)}" aria-describedby="g-hint-${k}"><p class="driver-help" id="g-hint-${k}"><span class="sr-only">${esc(unitDescription)}. </span>${k==='targetMargin'?`<span data-visible-help="targetMargin">${help}</span>`:help}</p><div class="field-evidence-actions"><button type="button" class="text-button" data-evidence="why-${k}">Why this assumption?</button><button type="button" class="text-button" data-evidence="history-${k}">View history</button></div><div hidden><div data-evidence-source="history-${k}">${historyPanel(k)}</div><div data-evidence-source="why-${k}">${researchRationale(k)||`<p>${esc(help)}</p><p>This is your editable forward-looking judgment. No researched value is available for this exact field.</p>`}</div></div></article>`;
}
function note(k,label,placeholder='What evidence supports this? What would change your mind?'){return `<details class="research-note"><summary>${label} <span>Optional note</span></summary><label class="sr-only" for="note-${k}">${label}</label><textarea id="note-${k}" data-note="${k}" placeholder="${esc(placeholder)}">${esc(draft.notes[k]||'')}</textarea></details>`}
function sourceEvidence(){
 const fields=[['Revenue',snapshot.revenue],['Operating profit',snapshot.ebit],['Cash & securities',snapshot.cash],['Mapped debt',snapshot.debt],['Shares · millions',snapshot.shares],['Operating margin',snapshot.ebit/snapshot.revenue]];
 return `<div class="source-facts">${fields.map(([label,v],i)=>`<div><span>${label}</span><b>${i===5?pc(v):num(v)}</b></div>`).join('')}</div><p class="micro">Amounts in ${esc(snapshot.currency)} millions except margin. ${esc(raw.derivation||'Reported filing inputs; no automatic accounting normalization.')}</p><a href="${esc(safeURL(snapshot.sourceUrl))}" target="_blank" rel="noopener">Open original filing ↗</a><details><summary>Field-level evidence ledger</summary>${table('Field-level evidence ledger',['Field','Value','Evidence'],Object.entries(raw.facts||{}).map(([k,v])=>[esc(k),num(v),v===null?'Missing':raw.factEvidence?.[k]?.formula||raw.factEvidence?.[k]?.derivation?'Derived from filing components':raw.factEvidence?.[k]?.originalInlineVerified||raw.factEvidence?.[k]?.originalDocumentVerified?'Original filing verified':'Source-linked']))}<a href="./data/current-universe.json" target="_blank" rel="noopener">Complete source ledger ↗</a></details><p class="design-notebook-link"><a href="./data/design-notebook.html">Design notebook & change log ↗</a></p>`;
}
function worksheet(){return `<details class="wacc-worksheet"><summary>Build WACC from its components <span>Optional worksheet</span></summary><p class="micro">Complete all seven inputs to use the calculated WACC automatically. Editing WACC directly switches back to your scalar assumption. No market reference is inserted automatically.</p><div class="worksheet-grid">${[['riskFree','Risk-free rate',100,'%'],['beta','Levered equity beta',1,'×'],['equityPremium','Equity risk premium',100,'%'],['countryPremium','Country-risk premium',100,'%'],['costOfDebt','Pretax cost of debt',100,'%'],['debtWeight','Debt / market capital',100,'%'],['tax','Marginal tax rate',100,'%']].map(([k,label,scale,u])=>`<label for="wacc-${k}">${label} · ${u}<input id="wacc-${k}" data-wacc="${k}" data-scale="${scale}" type="number" inputmode="decimal" step=".1" min="0" ${precisionInputAttributes(draft.waccWorksheet?.[k],scale)}></label>`).join('')}</div><p id="wacc-output" class="micro" role="status"></p></details>`}
function isFlexible(){return draft.operatingProfile?.id==='flexible-growth-v1'}
function operatingProfilePanel(){if(company.ticker!=='AAOI'||raw.id!=='AAOI-TTM-2026-06-30'||!claimsDefinition(snapshot))return '';const staged=draft.operatingProfile?.id==='aaoi-capacity-ramp-v1';return `<section class="operating-profile-panel"><label for="operating-profile">Operating path<select id="operating-profile"><option value="aaoi-capacity-ramp-v1" ${staged?'selected':''}>Staged capacity research case · 10 years</option><option value="linear-v1" ${!staged&&!isFlexible()?'selected':''}>Legacy linear path · operating stress</option><option value="flexible-growth-v1" ${isFlexible()?'selected':''}>Flexible growth and maturity</option></select></label><p>${staged?'Front-loaded growth, staged profitability, and initial sales/capital that improves with utilization before fading to terminal-consistent capital intensity. The same path shapes every simulated draw. The documented profile is fixed at 10 years; deliberately choose Flexible growth to use another maturity.':isFlexible()?'Your selected growth and maturity replace the documented AAOI capacity schedule. Review the new margin and capital path in Details.':'Your existing linear-path inputs are preserved. This slow margin transition can produce severe cash burn; it is an operating stress, not a validated fair-value case.'}</p><a href="./data/current-claims-research.json" target="_blank" rel="noopener">Path assumptions & source evidence ↗</a></section>`}
function growthTimings(){const p=draft.operatingProfile;return {marginMaturityYears:draft.marginPath?.enabled?draft.marginPath.terminalYear:p?.id==='aaoi-capacity-ramp-v1'?6:p?.schemaVersion===2?p.marginMaturityYears:draft.assumptions.years,capitalHoldYears:draft.capitalPath?.enabled?(isYearlyCapitalPath(draft.capitalPath)?1+(draft.capitalPath.yearlySalesCapital?.length||0):draft.capitalPath.fadeStartYear):p?.schemaVersion===2?p.capitalHoldYears:p?.explicitYears||0,capitalMaturityYears:draft.capitalPath?.enabled?draft.capitalPath.terminalYear:p?.schemaVersion===2?p.capitalMaturityYears:draft.assumptions.years};}
function timingInputs(kind){
 if(!isFlexible()||(kind==='margin'&&draft.marginPath?.enabled)||(kind==='capital'&&draft.capitalPath?.enabled))return '';
 const t=growthTimings(),fields=kind==='margin'?[['marginMaturityYears','Margin reaches target in year',1,30]]:[['capitalHoldYears','Capital efficiency starts changing after year',0,29],['capitalMaturityYears','Capital reaches mature efficiency in year',1,30]];
 return `<section class="operating-timing-controls" aria-label="${kind==='margin'?'Profitability':'Capital efficiency'} timing"><h3>${kind==='margin'?'When does the margin mature?':'When does capital efficiency mature?'}</h3><div class="operating-timing-inputs">${fields.map(([key,label,min,max])=>`<div><label for="timing-${key}">${label}</label><input id="timing-${key}" data-operating-timing="${key}" type="number" inputmode="numeric" min="${min}" max="${max}" step="1" ${precisionInputAttributes(t[key])} aria-describedby="operating-timing-help-${kind}"></div>`).join('')}</div><details class="timing-method"><summary>About separate timing</summary><p id="operating-timing-help-${kind}" class="micro">${kind==='margin'?'The margin then stays at its target. Changing the revenue-growth duration leaves this timing unchanged.':'Initial sales / capital stays fixed through the starting year above, then changes gradually to mature efficiency. Extra revenue still requires extra capital. These timings stay fixed when you change revenue-growth duration.'}</p></details></section>`;
}
function interimMarginDefaults(){const terminalYear=growthTimings().marginMaturityYears||10;return {version:'interim-margin-path-v1',enabled:false,interimMargin:draft.assumptions.targetMargin,interimYear:Math.min(3,terminalYear),declineStartYear:Math.max(Math.min(3,terminalYear),terminalYear-3),terminalYear};}
function guidedMarginDefaults(){return draft.marginPath||interimMarginDefaults();}
function guidedMarginControls(){return marginPhaseControlsHTML('guided',guidedMarginDefaults(),{terminalMargin:draft.assumptions.targetMargin,terminalInput:false,source:'Starting margin uses normalized current EBIT / revenue.',yearlyOption:true});}
function guidedCapitalDefaults(){return draft.capitalPath||{...capitalPathDefaults(draft),enabled:false};}
function guidedCapitalControls(){return capitalPhaseControlsHTML('guided',guidedCapitalDefaults(),{description:capitalPathModeDescription(draft),yearlyOption:true,initialSalesCapital:draft.assumptions.salesCapital});}
// The path as the model currently computes it, year by year. Switching to
// "Set each year" starts from these values, so the valuation does not jump.
function modeledPath(kind){
 try{const v=calculateCurrent(snapshot,draft),path=v.operatingProfile?.annualPath;return v.rows.map((r,i)=>kind==='margin'?r.ebit/r.revenue:path?.[i]?.salesCapital??draft.assumptions.salesCapital).map(x=>Number.isFinite(x)?x:null);}
 catch{const a=draft.assumptions,start=(snapshot.ebit+draft.normalizationDelta)/snapshot.revenue,n=Number.isInteger(a.years)?a.years:10;return Array.from({length:n},(_,i)=>kind==='margin'?start+(a.targetMargin-start)*(i+1)/n:a.salesCapital);}
}
const roundTo=(v,step)=>Number.isFinite(v)?Math.round(v/step)*step:v;
function yearlyMarginStart(){
 const prior=draft.marginPath;if(isYearlyMarginPath(prior))return {...structuredClone(prior),enabled:true};
 // Set years run until the current path starts its final straight glide, so
 // the yearly path reproduces it (to the displayed 0.1 pp).
 const values=modeledPath('margin'),maturity=growthTimings().marginMaturityYears||10,interim=prior?.enabled===true?prior:null;
 let k=interim?interim.declineStartYear:draft.operatingProfile?.id==='aaoi-capacity-ramp-v1'?5:Math.min(3,maturity-1),T=interim?interim.terminalYear:maturity;
 k=Math.max(1,Math.min(MAX_NEAR_TERM_YEARS,k||1));T=Math.min(30,Math.max(T||10,k+1));
 return {enabled:true,version:YEARLY_MARGIN_PATH_VERSION,nearTermMargins:Array.from({length:k},(_,i)=>Number(roundTo(values[i]??draft.assumptions.targetMargin,.001).toFixed(4))),terminalYear:T};
}
function yearlyCapitalStart(){
 const prior=draft.capitalPath;if(isYearlyCapitalPath(prior))return {...structuredClone(prior),enabled:true};
 // Set years run until the current path starts fading to its terminal level.
 // A constant ratio never fades inside the forecast, so every year is set.
 const values=modeledPath('capital'),profile=draft.operatingProfile,phased=prior?.enabled===true?prior:null;
 let k,T;
 if(phased){k=phased.fadeStartYear;T=phased.terminalYear;}
 else if(profile?.id==='flexible-growth-v1'){k=profile.schemaVersion===2?profile.capitalHoldYears:profile.explicitYears;T=profile.schemaVersion===2?profile.capitalMaturityYears:draft.assumptions.years;}
 else if(profile?.id==='aaoi-capacity-ramp-v1'){k=7;T=10;}
 else{k=values.length;T=values.length+1;}
 k=Math.max(1,Math.min(MAX_YEARLY_CAPITAL_YEARS,k||1));T=Math.min(30,Math.max(T||10,k+1));
 return {enabled:true,version:YEARLY_CAPITAL_PATH_VERSION,yearlySalesCapital:Array.from({length:k-1},(_,i)=>Number(roundTo(values[i+1]??draft.assumptions.salesCapital,.01).toFixed(2))),terminalYear:T};
}
// Glide value for a year past the set years, used when another year is added.
function glideValue(kind,year){
 if(kind==='margin'){const p=draft.marginPath,m=p.nearTermMargins,k=m.length,last=m[k-1],target=draft.assumptions.targetMargin;return Number(roundTo(year>=p.terminalYear?target:last+(target-last)*(year-k)/(p.terminalYear-k),.001).toFixed(4));}
 const values=modeledPath('capital');return Number(roundTo(values[year-1]??draft.assumptions.salesCapital,.01).toFixed(2));
}
const yearlyStash=new Map();
function resizeYearly(kind,count){
 const margin=kind==='margin',p=margin?draft.marginPath:draft.capitalPath,max=margin?MAX_NEAR_TERM_YEARS:MAX_YEARLY_CAPITAL_YEARS;
 if(!(margin?isYearlyMarginPath(p):isYearlyCapitalPath(p))||!Number.isInteger(count))return false;
 const k=Math.max(1,Math.min(max,count)),values=[...(margin?p.nearTermMargins:p.yearlySalesCapital)],first=margin?1:2,current=values.length+first-1;
 if(k===current)return false;
 rememberEdit((margin?'marginPath':'capitalPath')+':years');
 // Years you drop are remembered, so shrinking and growing again restores them.
 const stash=yearlyStash.get(key()+kind)||[];
 for(let year=k+1;year<=current;year++)stash[year]=values[year-first];
 for(let year=current+1;year<=k;year++)values.push(stash[year]??glideValue(kind,year));
 yearlyStash.set(key()+kind,stash);
 values.length=k-first+1;
 const next={...p,[margin?'nearTermMargins':'yearlySalesCapital']:values,terminalYear:Math.min(30,Math.max(p.terminalYear,k+1))};
 if(margin)draft.marginPath=next;else draft.capitalPath=next;
 markDraftEdited(draft,margin?'marginPath':'capitalPath');return true;
}
// Year-by-year values for presentation layers (the path chart in the skin).
const pathData=(el,values)=>{for(const [name,value] of Object.entries(values)){const text=String(value);if(el.getAttribute(name)!==text)el.setAttribute(name,text);}};
function publishPaths(value){
 const margin=app.querySelector('#editor-group-3 .margin-phase-controls'),capital=app.querySelector('#editor-group-4 .capital-phase-controls'),growth=app.querySelector('#editor-group-2 .growth-path-controls'),a=draft.assumptions;
 const rows=value?.rows||[],path=value?.operatingProfile?.annualPath,clean=v=>Number.isFinite(v)?Number(v.toPrecision(10)):null;
 // Growth: year 1 is the headline assumption; "Set each year" adds years 2…N.
 if(growth)pathData(growth,{'data-path':JSON.stringify(rows.map(r=>clean(r.growth))),'data-start':String(clean(a.growth)),'data-mature':String(clean(a.terminalGrowth)),'data-set-years':String(isFlexible()&&draft.operatingProfile.mode==='annual'?draft.operatingProfile.explicitYears:1)});
 if(margin)pathData(margin,{'data-path':JSON.stringify(rows.map(r=>clean(r.ebit/r.revenue))),'data-start':String(clean((snapshot.ebit+draft.normalizationDelta)/snapshot.revenue)),'data-mature':String(clean(a.targetMargin)),'data-set-years':String(isYearlyMarginPath(draft.marginPath)&&draft.marginPath.enabled?draft.marginPath.nearTermMargins?.length||0:0)});
 if(capital){
  const terminal=(1+a.terminalGrowth)*a.targetMargin*(1-a.tax)/a.terminalROIC;
  pathData(capital,{'data-path':JSON.stringify(rows.map((r,i)=>clean(path?.[i]?.salesCapital??a.salesCapital))),'data-start':String(clean(a.salesCapital)),'data-mature':String(clean(terminal>0?1/terminal:NaN)),'data-roic':String(clean(a.terminalROIC)),'data-set-years':String(isYearlyCapitalPath(draft.capitalPath)&&draft.capitalPath.enabled?1+(draft.capitalPath.yearlySalesCapital?.length||0):0)});
  const linked=capital.querySelector('input[data-linked="salesCapital"]');if(linked&&document.activeElement!==linked&&Number.isFinite(a.salesCapital))setPrecisionInput(linked,a.salesCapital,1);
 }
}
function timelineSummary(){if(!isFlexible()&&!draft.capitalPath?.enabled)return '';const t=growthTimings();return `Growth reaches its stable rate in year ${draft.assumptions.years}; margin matures in year ${t.marginMaturityYears}; capital efficiency matures in year ${t.capitalMaturityYears}.`;}
function growthPathControls(){
 const p=draft.operatingProfile,flex=isFlexible(),staged=p?.id==='aaoi-capacity-ramp-v1',mode=flex?(p.mode==='immediate'?'immediate':p.mode+p.explicitYears):staged?'staged':'legacy',explicit=flex&&p.mode!=='immediate',annual=flex&&p.mode==='annual',period=explicit?p.explicitYears:5;
 const options=[['immediate','Fade from year 1'],['maintain'+period,'Hold the same growth'],['annual'+period,'Set each year’s growth'],['legacy','Original model · 10 years'],...(staged?[['staged','AAOI capacity research · 10 years']]:[])];
 const annualInputs=annual?`<fieldset class="annual-growth-group"><legend>Your annual revenue growth · %</legend><div class="annual-growth-inputs"><div><label for="g-growth">Year 1</label><input id="g-growth" type="number" inputmode="decimal" data-assumption="growth" data-scale="100" min="-30" max="100" step=".5" ${precisionInputAttributes(draft.assumptions.growth,100)} aria-describedby="g-hint-growth"></div>${Array.from({length:p.explicitYears-1},(_,i)=>`<div><label for="growth-year-${i+2}">Year ${i+2}</label><input id="growth-year-${i+2}" data-annual-growth="${i}" type="number" inputmode="decimal" min="-50" max="200" step=".5" ${precisionInputAttributes(p.subsequentGrowth?.[i],100)} aria-describedby="annual-growth-help"></div>`).join('')}</div><p id="g-hint-growth" class="micro">Enter each year above. After year ${p.explicitYears}, growth gradually fades to your stable-growth rate.</p><details class="annual-growth-method"><summary>How these rates are used</summary><p id="annual-growth-help" class="micro">Later rates start from your prior path when you select this pattern and stay editable. With legacy simulation, one sampled year-1 growth shifts all explicit rates by the same percentage points. Correlated annual growth paths instead vary unfixed years around this path. Both methods retain fixed stable growth. Invalid years are excluded, never clipped.</p></details></fieldset>`:'';
 return `<section class="growth-path-controls" aria-labelledby="growth-path-title"><h3 id="growth-path-title">Revenue growth path</h3><div class="growth-path-selects${explicit?' growth-path-selects--explicit':''}"><div class="growth-pattern-choice"><label for="growth-path-mode">Growth pattern</label><select id="growth-path-mode" aria-describedby="growth-path-help">${options.map(([id,label])=>`<option value="${id}" ${mode===id?'selected':''}>${label}</option>`).join('')}</select></div>${explicit?`<div><label for="growth-explicit-years">${annual?'Set each year through':'Hold the same rate through'}</label><select id="growth-explicit-years" aria-describedby="growth-path-help">${[3,5].map(n=>`<option value="${n}" ${p.explicitYears===n?'selected':''}>Year ${n}</option>`).join('')}</select></div>`:''}<div><label for="growth-maturity">Growth reaches stable rate in year</label><select id="growth-maturity" aria-describedby="growth-path-help" ${!flex?'disabled':''}>${[10,15,20].map(n=>`<option value="${n}" ${draft.assumptions.years===n?'selected':''}>Year ${n}</option>`).join('')}</select></div></div><p id="growth-path-help" class="micro">${flex?(p.mode==='immediate'?`Growth fades immediately to the stable rate in year ${draft.assumptions.years}.`:`${p.explicitYears} explicit growth years, then ${draft.assumptions.years-p.explicitYears} fade years to the stable rate.`)+` Margin matures in year ${growthTimings().marginMaturityYears}; capital efficiency in year ${growthTimings().capitalMaturityYears}. Changing growth duration leaves those timings unchanged.`:draft.capitalPath?.enabled?'Growth keeps its existing 10-year schedule. Capital efficiency follows the separate early/later phase dates in Investment.':'The original model keeps its existing 10-year economics. Choose a growth pattern above to set the timing yourself.'}</p>${annualInputs}<div id="growth-path-action-status" class="micro" role="status"></div>${undoOperatingPaths.has(key())?'<button id="undo-growth-path" class="text-button">Undo path change</button>':''}<details class="growth-method"><summary>How maturity changes the model</summary><p>Choose a duration from competitive advantage, business size and reinvestment needs. A longer growth period does not establish a longer competitive advantage. The forecast runs until growth, margin and capital efficiency have all reached their mature settings. No future market share is inferred.</p><p>Margin timing is set in Profitability; capital-efficiency timing is set in Investment. Each stays unchanged when you edit growth. Initial sales / capital is held through its own starting period, then capital intensity fades to the terminal growth, margin, tax and ROIC assumptions. Mature marginal ROIC is your separate input; it is not automatically set equal to WACC. Constant WACC assumes risk is representative throughout, with no capital-structure transition.</p><a href="./data/growth-methodology.html" target="_blank" rel="noopener">Formulas, sources & limitations ↗</a>${company.ticker==='GOOG'?'<p><a href="./data/goog-valuation-audit.html" target="_blank" rel="noopener">Alphabet audit & path comparisons ↗</a></p>':''}</details></section>${annual?`<div class="field-evidence-actions"><button class="text-button" data-evidence="annual-growth">Why this path? / View history</button></div><div hidden><div class="annual-growth-evidence" data-evidence-source="annual-growth">${researchRationale('growth')}${historyPanel('growth')}</div></div>`:''}`;
}
function changeGrowthPath(mode,years=draft.assumptions.years,focusId='growth-path-mode'){
 inputUndo.delete(key());activeEdit=null;
 const before={operatingProfile:structuredClone(draft.operatingProfile),years:draft.assumptions.years,restoreProfile:true};let previous=[];try{const a=operatingAssumptions(snapshot,draft,draft.assumptions);previous=a.yearlyOverrides||Array.from({length:a.years},(_,i)=>({growth:a.growth+(a.terminalGrowth-a.growth)*i/(a.years-1)}));}catch{}
 undoOperatingPaths.set(key(),before);
 if(mode==='legacy'||mode==='staged'){draft.operatingProfile={schemaVersion:1,id:mode==='staged'?'aaoi-capacity-ramp-v1':'linear-v1'};draft.assumptions.years=10;}
 else{const explicitYears=mode==='immediate'?0:Number(mode.slice(-1)),annual=mode.startsWith('annual');draft.operatingProfile=independentGrowthProfile(draft,{mode:mode==='immediate'?'immediate':annual?'annual':'maintain',explicitYears,subsequentGrowth:annual?Array.from({length:explicitYears-1},(_,i)=>previous[i+1]?.growth??draft.assumptions.growth):[]});draft.assumptions.years=[10,15,20].includes(years)?years:10;}
 markDraftEdited(draft,'operatingProfile');store();render();if($('#growth-path-action-status'))$('#growth-path-action-status').textContent='Path changed. Your scalar inputs are retained; review the implied revenue and capital needs below.';$('#'+focusId)?.focus?.({preventScroll:true});
}

