function refreshDiagnostics(){const a=draft.assumptions;const capitalHelp=$('#guided-capital-help');if(capitalHelp)capitalHelp.textContent=capitalPathModeDescription(draft);if(isFlexible()&&$('#growth-path-help')){const t=growthTimings();$('#growth-path-help').textContent=$('#growth-path-help').textContent.replace(/Margin matures in year [^;]+; capital efficiency in year [^.]+\./,`Margin matures in year ${t.marginMaturityYears}; capital efficiency in year ${t.capitalMaturityYears}.`);const hint=$('#g-hint-targetMargin')?.querySelector('[data-visible-help="targetMargin"]');if(hint)hint.textContent=hint.textContent.replace(/by year [^,]+,/,`by year ${t.marginMaturityYears},`);}if($('#growth-scale')){try{const v=calculateCurrent(snapshot,draft),last=v.rows.find(r=>r.year===a.years)||v.rows.at(-1),capital=v.rows.reduce((sum,r)=>sum+r.reinvestment,0);$('#growth-scale').innerHTML=`In year ${a.years}, this path reaches <b>${num(last.revenue,0)}m ${esc(snapshot.currency)}</b> in revenue. That is <b>${num(last.revenue/snapshot.revenue,1)}×</b> today’s starting business.${isFlexible()?`<p>Forecast net reinvestment totals ${num(capital,0)}m ${esc(snapshot.currency)}. Mature marginal ROIC: ${pc(a.terminalROIC)}; terminal reinvestment: ${pc(a.terminalGrowth/a.terminalROIC)} of NOPAT. These are implied requirements, not observed capacity or market share.</p>${legacyPathComparison(v)}`:''}`;}catch{$('#growth-scale').textContent='Revenue scale is unavailable until the path and model inputs are valid.';}}if($('#capital-per-dollar'))$('#capital-per-dollar').textContent=num(1/a.salesCapital,2);if($('#stable-reinvestment'))$('#stable-reinvestment').textContent=pc(a.terminalGrowth/a.terminalROIC)}

