function fundingDiagnostics(v){let cumulative=0,trough=0;for(const r of v.rows){cumulative+=r.fcff;trough=Math.min(trough,cumulative)}const negative=v.rows.filter(r=>r.fcff<0).length;return `<div class="funding-diagnostic"><b>${negative} of ${v.rows.length} years have negative FCFF.</b><p>Peak cumulative undiscounted operating cash deficit: ${num(-trough,1)}m USD, before financing, minimum liquidity, coupons and obligations. Cash at the selected bridge reference is ${num(v.claimsBridge?.cash??snapshot.cash,1)}m. This is a funding-stress diagnostic; the model does not forecast issuance, default, recovery or a self-funded turnaround.</p></div><h3>Margin × capital productivity</h3><p class="micro">Illustrative operating stresses, holding your growth, WACC, terminal assumptions and claims treatment constant. These are conditional alternatives, not calibrated forecasts.</p>${table('Margin and capital-productivity stresses',['Mature EBIT margin','0.8× sales / capital','1.6× sales / capital','2.4× sales / capital'],[.12,.18].map(m=>[pc(m),...[.8,1.6,2.4].map(sc=>{try{return num(calculateCurrent(snapshot,{...draft,assumptions:{...draft.assumptions,targetMargin:m,salesCapital:sc}}).perShare,2)+' USD'}catch{return 'Unavailable'}})]))}`}
