const openingValues=new Map();
function openingChange(v){
 const identity=key(),basis=[snapshot.currency,snapshot.shareBasis,v.claimsBridge?.referenceDate||'',v.claimsBridge?.capitalBasis||''].join('|');
 if(!openingValues.has(identity))openingValues.set(identity,{value:v.perShare,basis,assumptions:structuredClone(draft.assumptions)});
 const start=openingValues.get(identity);
 if(start.basis!==basis)return '<p class="value-change comparison-unavailable">Starting-case comparison is unavailable across different capital or share bases.</p>';
 const delta=v.perShare-start.value,sign=delta>0?'+':delta<0?'−':'',percentage=start.value>0?` · ${sign}${num(Math.abs(delta/start.value)*100,1)}%`:'';
 const changes=[['growth','Near-term growth'],['targetMargin','Mature EBIT margin'],['salesCapital','Sales / capital'],['tax','Cash tax'],['wacc','WACC'],['terminalGrowth','Stable growth'],['terminalROIC','Terminal ROIC']].filter(([field])=>draft.assumptions[field]!==start.assumptions[field]);
 const explanation=changes.length?changes.slice(0,2).map(([field,label])=>`${label}: ${field==='salesCapital'?num(start.assumptions[field],2)+'×':pc(start.assumptions[field])} → ${field==='salesCapital'?num(draft.assumptions[field],2)+'×':pc(draft.assumptions[field])}`).join(' · ')+'. Total effect of all changes since opening.':'Compared with this company and financial period’s opening draft this session.';
 return `<p class="value-change" data-value-change="guided">${sign}${num(Math.abs(delta),2)} ${esc(snapshot.currency)} / share${percentage} from starting case</p><p class="comparison-basis">${esc(explanation)} Model change, not investment return.</p>`;
}
function compactOperatingValue(value,currency){const magnitude=Math.abs(value),scale=magnitude>=1e6?1e6:magnitude>=1000?1000:1,unit=scale===1e6?'T':scale===1000?'B':'M';return `${value<0?'−':''}${currency==='USD'?'$':currency==='TWD'?'NT$':esc(currency)+' '}${num(magnitude/scale,2)}${unit}`;}
function cashflowVisual(v){
 const rows=v.rows,values=rows.flatMap(r=>[r.ebit,r.fcff]),lo=Math.min(0,...values),hi=Math.max(1,...values),span=hi-lo||1,w=720,h=230,left=56,right=704,top=24,bottom=190,y=value=>bottom-(value-lo)/span*(bottom-top),step=(right-left)/rows.length;
 return `<div class="visual-heading"><div><span class="eyebrow">THE OPERATING STORY</span><h2>Growth must become cash.</h2></div><span>${rows.length} years · ${esc(snapshot.currency)} millions</span></div><svg class="cashflow-visual" viewBox="0 0 ${w} ${h}" role="img" aria-label="Annual operating profit and free cash flow. Exact figures in Tables."><line x1="${left}" x2="${right}" y1="${y(0)}" y2="${y(0)}" stroke="currentColor" opacity=".25"/>${rows.map((r,i)=>`<rect x="${left+i*step+step*.15}" y="${Math.min(y(0),y(r.ebit))}" width="${step*.3}" height="${Math.max(1,Math.abs(y(0)-y(r.ebit)))}" fill="var(--chart-two)"/><rect x="${left+i*step+step*.49}" y="${Math.min(y(0),y(r.fcff))}" width="${step*.3}" height="${Math.max(1,Math.abs(y(0)-y(r.fcff)))}" fill="var(--accent)"/><text class="chart-year-label${i===0||i===rows.length-1||r.year%5===0?' chart-key-year':''}" x="${left+(i+.5)*step}" y="214" text-anchor="middle" fill="currentColor" font-size="14">${r.year}</text>`).join('')}<text x="8" y="${y(hi)+5}" fill="currentColor" font-size="14">${num(hi>=1000?hi/1000:hi,1)}${hi>=1000?'k':''}</text><text x="8" y="${y(lo)+5}" fill="currentColor" font-size="14">${num(Math.abs(lo)>=1000?lo/1000:lo,1)}${Math.abs(lo)>=1000?'k':''}</text></svg><div class="visual-legend"><span><i style="background:var(--chart-two)"></i>Operating profit</span><span><i style="background:var(--accent)"></i>Free cash flow</span></div><p class="micro">${v.enterprise>0?`Terminal value supplies ${pc(v.terminalShare)} of operating value.`:'Negative operating value is preserved.'} Annual values and reinvestment are in Tables.</p>`;
}
