 if(isFlexible()||draft.capitalPath?.enabled)$('#guided-results').innerHTML+=`<p class="valuation-timing-note"><span>${esc(timelineSummary())}</span>${v.rows.length!==draft.assumptions.years?` <span>Full cash-flow forecast: ${v.rows.length} years.</span>`:''}</p>`;
 if($('#open-claims-model'))$('#open-claims-model').onclick=e=>{e.preventDefault();go(6)};
