 {const clean=x=>Number.isFinite(x)?Number(x.toPrecision(10)):null;pathData($('#guided-results'),{'data-bridge':JSON.stringify({forecastPV:clean(v.forecastPV),terminalPV:clean(v.terminalPV),enterprise:clean(v.enterprise),equity:clean(v.equity),perShare:clean(v.perShare),years:v.rows.length,currency:snapshot.currency})});}
 refreshClaimsCalculation(v);
 if($('#quote-comparison'))$('#quote-comparison').textContent=q.status==='ready'?`${num(q.price,2)} ${snapshot.currency} on ${q.date} · value-to-price gap ${pc(q.gap)}. Not an expected return.`:q.message;
 if($('#forecast-detail'))$('#forecast-detail').innerHTML=`<div class="detail-metrics"><div><span>Terminal PV share</span><b>${v.enterprise>0?pc(v.terminalShare):'Not meaningful'}</b></div><div><span>Common equity</span><b>${num(v.equity,0)}m</b></div></div><p class="micro">${v.enterprise>0?'A high terminal share means value depends heavily on mature growth, returns and discount rate.':'Terminal-value share is not meaningful when operating enterprise value is nonpositive.'}</p>${isFlexible()||draft.capitalPath?.enabled?`<p class="micro"><span>${esc(timelineSummary())}</span> <span>The cash-flow forecast covers ${v.rows.length} years, through the latest maturity.</span></p>`:''}${company.ticker==='AAOI'?fundingDiagnostics(v):''}${v.operatingProfile?`<details open><summary>${draft.capitalPath?.enabled?"Independent capital":isFlexible()?"Flexible":"Staged"} annual path · applied to every scenario</summary>${table(draft.capitalPath?.enabled?'Independent capital annual operating path':isFlexible()?'Flexible annual operating path':'Staged annual operating path',['Year','Growth','EBIT margin','Sales / capital'],v.operatingProfile.annualPath.map((r,i)=>[i+1,pc(r.growth),pc(r.margin),num(r.salesCapital,3)+'×']))}<p class="micro">${draft.capitalPath?.enabled?esc(capitalPathModeDescription(draft))+' ':''}${draft.capitalPath?.enabled||isFlexible()||draft.operatingProfile?.id==='aaoi-capacity-ramp-v1'?`Capital intensity in year ${v.rows.length} (mature since year ${growthTimings().capitalMaturityYears}) =`:'Terminal-consistent reference intensity ='} (1 + stable growth) × mature margin × (1 − tax) / terminal ROIC. This matches the terminal reinvestment timing. The profile is an analyst assumption; default, recovery and financing are not modeled.${isFlexible()?` ${esc(v.operatingProfile.growthSampling)} ${esc(v.operatingProfile.risk)}`:""}</p></details>`:''}${table('Annual cash-flow forecast',['Year','Revenue','EBIT','Reinvestment','FCFF'],v.rows.map(r=>[r.year,num(r.revenue),num(r.ebit),num(r.reinvestment),num(r.fcff)]))}<h3>Illustrative stresses</h3><div class="stress-cases">${[['Downside',-.03,-.03,.01],['Base',0,0,0],['Upside',.03,.03,-.01]].map(([label,g,m,w])=>{let amount;try{amount=valueCurrentWithClaims(snapshot,draft,{...draft.assumptions,growth:draft.assumptions.growth+g,targetMargin:Math.max(0,draft.assumptions.targetMargin+m),wacc:draft.assumptions.wacc+w}).perShare}catch{}return `<div><span>${label}</span><b>${num(amount,2)}</b></div>`}).join('')}</div><p class="micro">Growth and margin ±3pp; WACC ∓1pp. These are stress tests, not estimated probabilities.</p>`;
