 if(simulationTimer!==null)clearTimeout(simulationTimer);
 if(!refreshSimulation)return;
 // Cancel in-flight runs immediately; the debounce never leaves old values labeled current.
 releaseSimulation.pending?.();
 const mount=()=>{releaseSimulation();const simulationDraft=draft;releaseSimulation=mountSimulation($('#simulation-lab'),snapshot,draft,{animateChange:edit&&!firstMount,onConfigChange:config=>{if(draft!==simulationDraft)return;draft.simulationConfig=config;markDraftEdited(draft,'simulationConfig');store();}});firstMount=false;simulationTimer=null};
 if(edit)simulationTimer=setTimeout(mount,120);else mount();
